using Dapper;using FinOS.Common.Interfaces;using FinOS.CoreFinance.Domain.Entities;using FinOS.CoreFinance.Domain.Interfaces;
namespace FinOS.CoreFinance.Infrastructure.Repositories;
public class CreditCardRepository(IConnectionFactory f):ICreditCardRepository{
public async Task<IReadOnlyList<CreditCardDetail>> GetAsync(long u,CancellationToken ct=default){using var c=f.CreateConnection();return(await c.QueryAsync<CreditCardDetail>(@"SELECT a.Id AccountId,a.UserId,a.Name,a.InstitutionName,a.Balance,a.CreditLimit,d.StatementDay,d.PaymentDueDay,ISNULL(d.MinimumAmountDue,0) MinimumAmountDue,ISNULL(d.TotalAmountDue,ABS(CASE WHEN a.Balance<0 THEN a.Balance ELSE 0 END)) TotalAmountDue,ISNULL(d.AnnualInterestRate,0) AnnualInterestRate,d.LastPaymentDate,d.LastPaymentAmount FROM Core.Accounts a JOIN Core.AccountTypes t ON t.Id=a.AccountTypeId LEFT JOIN Core.CreditCardDetails d ON d.AccountId=a.Id WHERE a.UserId=@u AND t.Name=N'CreditCard' AND a.DeletedAt IS NULL",new{u})).ToList();}
public async Task<CreditCardDetail?> UpsertAsync(CreditCardDetail x,CancellationToken ct=default){using var c=f.CreateConnection();var owned=await c.ExecuteScalarAsync<int>("SELECT COUNT(1) FROM Core.Accounts a JOIN Core.AccountTypes t ON t.Id=a.AccountTypeId WHERE a.Id=@AccountId AND a.UserId=@UserId AND t.Name=N'CreditCard' AND a.DeletedAt IS NULL",x);if(owned==0)return null;await c.ExecuteAsync(@"MERGE Core.CreditCardDetails AS d USING(SELECT @AccountId AccountId) s ON d.AccountId=s.AccountId WHEN MATCHED THEN UPDATE SET StatementDay=@StatementDay,PaymentDueDay=@PaymentDueDay,MinimumAmountDue=@MinimumAmountDue,TotalAmountDue=@TotalAmountDue,AnnualInterestRate=@AnnualInterestRate,LastPaymentDate=@LastPaymentDate,LastPaymentAmount=@LastPaymentAmount,UpdatedAt=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(AccountId,UserId,StatementDay,PaymentDueDay,MinimumAmountDue,TotalAmountDue,AnnualInterestRate,LastPaymentDate,LastPaymentAmount)VALUES(@AccountId,@UserId,@StatementDay,@PaymentDueDay,@MinimumAmountDue,@TotalAmountDue,@AnnualInterestRate,@LastPaymentDate,@LastPaymentAmount);",x);return x;}}
